CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "AlumniEvents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" character varying(200) NOT NULL,
    "Description" text NOT NULL,
    "Date" timestamp with time zone NOT NULL,
    "Location" character varying(200) NOT NULL,
    "RegistrationFee" numeric,
    "RequiresPayment" boolean NOT NULL,
    "IsActive" boolean NOT NULL,
    "AllowNonMembers" boolean NOT NULL,
    "ImageUrl" character varying(500),
    "RegistrationDeadline" timestamp with time zone,
    "AdminNote" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_AlumniEvents" PRIMARY KEY ("Id")
);

CREATE TABLE "ContactMessages" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FullName" text NOT NULL,
    "Email" text NOT NULL,
    "Subject" text NOT NULL,
    "Message" text NOT NULL,
    "SubmittedAt" timestamp with time zone NOT NULL,
    "IsRead" boolean NOT NULL,
    CONSTRAINT "PK_ContactMessages" PRIMARY KEY ("Id")
);

CREATE TABLE "ECPeriods" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" text NOT NULL,
    "StartDate" timestamp with time zone NOT NULL,
    "EndDate" timestamp with time zone,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_ECPeriods" PRIMARY KEY ("Id")
);

CREATE TABLE "EmailLogs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RecipientEmail" character varying(200) NOT NULL,
    "Subject" character varying(500) NOT NULL,
    "Body" text NOT NULL,
    "TemplateCode" text,
    "SentDate" timestamp with time zone NOT NULL,
    "Status" character varying(100) NOT NULL,
    "ErrorMessage" text,
    "InitiatedByMemberId" integer,
    "TargetAudience" text,
    CONSTRAINT "PK_EmailLogs" PRIMARY KEY ("Id")
);

CREATE TABLE "EmailTemplates" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" character varying(50) NOT NULL,
    "Subject" character varying(200) NOT NULL,
    "Body" text NOT NULL,
    "Description" character varying(200) NOT NULL,
    "Variables" text,
    "LastUpdated" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_EmailTemplates" PRIMARY KEY ("Id")
);

CREATE TABLE "EventGalleries" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" text NOT NULL,
    "Description" text,
    "EventDate" timestamp with time zone NOT NULL,
    "Location" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedByAdminId" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    "IsFeatured" boolean NOT NULL,
    CONSTRAINT "PK_EventGalleries" PRIMARY KEY ("Id")
);

CREATE TABLE "FinancialRecords" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Year" integer NOT NULL,
    "RecordType" integer NOT NULL,
    "Category" integer NOT NULL,
    "Date" timestamp with time zone NOT NULL,
    "Amount" numeric NOT NULL,
    "Description" character varying(500) NOT NULL,
    "Reference" character varying(100),
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedByAdminId" integer NOT NULL,
    CONSTRAINT "PK_FinancialRecords" PRIMARY KEY ("Id")
);

CREATE TABLE "Lookups" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Category" character varying(50) NOT NULL,
    "Value" character varying(100) NOT NULL,
    "Label" character varying(200) NOT NULL,
    "IsActive" boolean NOT NULL,
    "DisplayOrder" integer NOT NULL,
    CONSTRAINT "PK_Lookups" PRIMARY KEY ("Id")
);

CREATE TABLE "Members" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FullName" character varying(200) NOT NULL,
    "FatherName" text NOT NULL,
    "MotherName" text NOT NULL,
    "DateOfBirth" timestamp with time zone NOT NULL,
    "Gender" integer NOT NULL,
    "BloodGroup" integer NOT NULL,
    "NID" text NOT NULL,
    "MobileNo" text NOT NULL,
    "Email" text NOT NULL,
    "EmailVerified" boolean NOT NULL,
    "PresentAddress" text NOT NULL,
    "PermanentAddress" text NOT NULL,
    "EmergencyContactName" text NOT NULL,
    "EmergencyContactRelation" text NOT NULL,
    "EmergencyContactPhone" text NOT NULL,
    "PhotoPath" text,
    "TShirtSize" text,
    "Status" integer NOT NULL,
    "AppliedDate" timestamp with time zone NOT NULL,
    "ApprovedDate" timestamp with time zone,
    "ApprovedBy" integer,
    "MembershipNumber" text,
    "IsMobilePublic" boolean NOT NULL,
    "IsEmailPublic" boolean NOT NULL,
    "IsAddressPublic" boolean NOT NULL,
    "IsNIDPublic" boolean NOT NULL,
    "HasAcceptedTerms" boolean NOT NULL,
    "IsArchived" boolean NOT NULL,
    "LastUpdateDate" timestamp with time zone NOT NULL,
    "MembershipType" integer NOT NULL,
    "Category" integer NOT NULL,
    CONSTRAINT "PK_Members" PRIMARY KEY ("Id")
);

CREATE TABLE "MembershipFeeConfigs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MembershipType" integer NOT NULL,
    "Amount" numeric NOT NULL,
    "EffectiveDate" timestamp with time zone NOT NULL,
    "Description" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedByAdminId" integer,
    CONSTRAINT "PK_MembershipFeeConfigs" PRIMARY KEY ("Id")
);

CREATE TABLE "Otps" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Email" text NOT NULL,
    "Code" text NOT NULL,
    "ExpiryAt" timestamp with time zone NOT NULL,
    "IsVerified" boolean NOT NULL,
    "Attempts" integer NOT NULL,
    "Purpose" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Otps" PRIMARY KEY ("Id")
);

CREATE TABLE "PaymentConfigurations" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Method" integer NOT NULL,
    "DisplayName" character varying(100) NOT NULL,
    "Description" character varying(500),
    "Icon" character varying(50),
    "IsEnabled" boolean NOT NULL,
    "WalletNumber" character varying(20),
    "AccountHolderName" character varying(100),
    "BankName" character varying(100),
    "BranchName" character varying(50),
    "AccountNumber" character varying(50),
    "RoutingNumber" character varying(50),
    "Gateway" integer NOT NULL,
    "GatewayPublicKey" character varying(500),
    "GatewaySecretKey" character varying(500),
    "GatewayCallbackUrl" character varying(500),
    "IsSandbox" boolean NOT NULL,
    "SortOrder" integer NOT NULL,
    "Instructions" character varying(1000),
    "RequiresReceipt" boolean NOT NULL,
    "RequiresReference" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_PaymentConfigurations" PRIMARY KEY ("Id")
);

CREATE TABLE "Roles" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    CONSTRAINT "PK_Roles" PRIMARY KEY ("Id")
);

CREATE TABLE "SpecialDayThemes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" character varying(100) NOT NULL,
    "StartDate" timestamp with time zone NOT NULL,
    "EndDate" timestamp with time zone NOT NULL,
    "BackgroundColor" character varying(7) NOT NULL,
    "TextColor" character varying(7) NOT NULL,
    "AnnouncementText" character varying(100) NOT NULL,
    "IsEnabled" boolean NOT NULL,
    CONSTRAINT "PK_SpecialDayThemes" PRIMARY KEY ("Id")
);

CREATE TABLE "EventPhotos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EventGalleryId" integer NOT NULL,
    "PhotoPath" text NOT NULL,
    "Caption" text,
    "UploadedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_EventPhotos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_EventPhotos_EventGalleries_EventGalleryId" FOREIGN KEY ("EventGalleryId") REFERENCES "EventGalleries" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AcademicRecords" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MemberId" integer NOT NULL,
    "InstitutionName" character varying(200) NOT NULL,
    "Degree" character varying(100) NOT NULL,
    "Subject" character varying(100) NOT NULL,
    "AdmissionYear" integer,
    "PassingYear" integer NOT NULL,
    "IsGHC" boolean NOT NULL,
    "Result" text,
    "CertificatePath" text,
    CONSTRAINT "PK_AcademicRecords" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AcademicRecords_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id") ON DELETE CASCADE
);

CREATE TABLE "ActivityLogs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MemberId" integer,
    "ActorId" integer,
    "ActivityType" text NOT NULL,
    "Description" text NOT NULL,
    "Timestamp" timestamp with time zone NOT NULL,
    "IPAddress" text,
    CONSTRAINT "PK_ActivityLogs" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ActivityLogs_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id")
);

CREATE TABLE "ChatMessages" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "SenderId" integer NOT NULL,
    "ReceiverId" integer NOT NULL,
    "MessageContent" text NOT NULL,
    "SentAt" timestamp with time zone NOT NULL,
    "IsRead" boolean NOT NULL,
    CONSTRAINT "PK_ChatMessages" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ChatMessages_Members_ReceiverId" FOREIGN KEY ("ReceiverId") REFERENCES "Members" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ChatMessages_Members_SenderId" FOREIGN KEY ("SenderId") REFERENCES "Members" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "ECMembers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MemberId" integer NOT NULL,
    "ECPeriodId" integer NOT NULL,
    "Position" integer NOT NULL,
    "StartDate" timestamp with time zone NOT NULL,
    "EndDate" timestamp with time zone,
    "ChangeReason" text,
    CONSTRAINT "PK_ECMembers" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ECMembers_ECPeriods_ECPeriodId" FOREIGN KEY ("ECPeriodId") REFERENCES "ECPeriods" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_ECMembers_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id") ON DELETE CASCADE
);

CREATE TABLE "EventRegistrations" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EventId" integer NOT NULL,
    "MemberId" integer,
    "IsNonMember" boolean NOT NULL,
    "GuestName" character varying(200),
    "GuestEmail" character varying(100),
    "GuestMobile" character varying(20),
    "PaymentReference" character varying(100),
    "ReceiptPath" character varying(500),
    "ContributionAmount" numeric,
    "PaymentMethod" integer NOT NULL,
    "Status" integer NOT NULL,
    "RegisteredAt" timestamp with time zone NOT NULL,
    "ApprovedAt" timestamp with time zone,
    "ApprovedByAdminId" integer,
    CONSTRAINT "PK_EventRegistrations" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_EventRegistrations_AlumniEvents_EventId" FOREIGN KEY ("EventId") REFERENCES "AlumniEvents" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_EventRegistrations_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id")
);

CREATE TABLE "FileUploads" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MemberId" integer NOT NULL,
    "UploadType" integer NOT NULL,
    "FileName" character varying(260) NOT NULL,
    "FilePath" text NOT NULL,
    "SizeBytes" bigint NOT NULL,
    "Status" integer NOT NULL,
    "UploadedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_FileUploads" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_FileUploads_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id") ON DELETE CASCADE
);

CREATE TABLE "JobOpportunities" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" text NOT NULL,
    "Company" text NOT NULL,
    "Location" text NOT NULL,
    "Description" text NOT NULL,
    "Requirements" text NOT NULL,
    "ContactEmail" text NOT NULL,
    "ApplicationLink" text,
    "PostedByMemberId" integer NOT NULL,
    "PostedDate" timestamp with time zone NOT NULL,
    "ExpiryDate" timestamp with time zone,
    "IsActive" boolean NOT NULL,
    "Category" integer NOT NULL,
    "PostedById" integer,
    CONSTRAINT "PK_JobOpportunities" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_JobOpportunities_Members_PostedById" FOREIGN KEY ("PostedById") REFERENCES "Members" ("Id")
);

CREATE TABLE "MembershipHistories" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MemberId" integer NOT NULL,
    "ChangedFrom" text NOT NULL,
    "ChangedTo" text NOT NULL,
    "ChangedByAdminId" integer,
    "ChangedAt" timestamp with time zone NOT NULL,
    "Reason" text,
    CONSTRAINT "PK_MembershipHistories" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_MembershipHistories_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Notifications" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MemberId" integer NOT NULL,
    "Title" text NOT NULL,
    "Message" text NOT NULL,
    "TargetUrl" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "IsRead" boolean NOT NULL,
    "Type" text NOT NULL,
    CONSTRAINT "PK_Notifications" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Notifications_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id") ON DELETE CASCADE
);

CREATE TABLE "PaymentHistories" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MemberId" integer NOT NULL,
    "TransactionId" text NOT NULL,
    "Amount" numeric NOT NULL,
    "PaidAt" timestamp with time zone NOT NULL,
    "Status" integer NOT NULL,
    "Category" integer NOT NULL,
    "Notes" text,
    "PaymentMethod" integer NOT NULL,
    "ReceiptPath" character varying(500),
    CONSTRAINT "PK_PaymentHistories" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PaymentHistories_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id") ON DELETE CASCADE
);

CREATE TABLE "ProfessionalRecords" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MemberId" integer NOT NULL,
    "OrganizationName" character varying(200) NOT NULL,
    "Designation" character varying(100) NOT NULL,
    "Sector" character varying(100),
    "Location" character varying(200),
    "StartDate" timestamp with time zone NOT NULL,
    "EndDate" timestamp with time zone,
    "IsCurrent" boolean NOT NULL,
    CONSTRAINT "PK_ProfessionalRecords" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ProfessionalRecords_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Username" character varying(100) NOT NULL,
    "PasswordHash" text NOT NULL,
    "MemberId" integer,
    "CreatedAt" timestamp with time zone NOT NULL,
    "IsActive" boolean NOT NULL,
    "IsArchived" boolean NOT NULL,
    "MustChangePassword" boolean NOT NULL,
    "ResetToken" text,
    "ResetTokenExpiry" timestamp with time zone,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Users_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id")
);

CREATE TABLE "MembershipDues" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MemberId" integer NOT NULL,
    "Year" integer NOT NULL,
    "Amount" numeric NOT NULL,
    "DueDate" timestamp with time zone NOT NULL,
    "IsPaid" boolean NOT NULL,
    "PaymentDate" timestamp with time zone,
    "PaymentHistoryId" integer,
    CONSTRAINT "PK_MembershipDues" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_MembershipDues_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_MembershipDues_PaymentHistories_PaymentHistoryId" FOREIGN KEY ("PaymentHistoryId") REFERENCES "PaymentHistories" ("Id")
);

CREATE TABLE "NewsPosts" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" character varying(200) NOT NULL,
    "Content" text NOT NULL,
    "Category" integer NOT NULL,
    "Status" integer NOT NULL,
    "PublishDate" timestamp with time zone NOT NULL,
    "IsActive" boolean NOT NULL,
    "ImageUrl" text,
    "AuthorId" integer NOT NULL,
    "LastModified" timestamp with time zone,
    CONSTRAINT "PK_NewsPosts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_NewsPosts_Users_AuthorId" FOREIGN KEY ("AuthorId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UserRoles" (
    "RolesId" integer NOT NULL,
    "UsersId" integer NOT NULL,
    CONSTRAINT "PK_UserRoles" PRIMARY KEY ("RolesId", "UsersId"),
    CONSTRAINT "FK_UserRoles_Roles_RolesId" FOREIGN KEY ("RolesId") REFERENCES "Roles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_UserRoles_Users_UsersId" FOREIGN KEY ("UsersId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

