INSERT INTO "EmailTemplates" ("Id", "Body", "Code", "Description", "LastUpdated", "Subject", "Variables")
VALUES (-8, '<div style=''font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;''><h2 style=''color: #27ae60;''>Link Request Accepted</h2><p>Hello <strong>{{FullName}}</strong>,</p><p>Your family link request to <strong>{{TargetName}}</strong> has been accepted.</p><p>You are now connected in the GHCAA network.</p></div>', 'FAMILY_LINK_ACCEPTED', 'Family link acceptance confirmation', TIMESTAMPTZ '2026-03-21T15:37:55.635897Z', 'Family Link Request Accepted', '[''FullName'', ''TargetName'']');
INSERT INTO "EmailTemplates" ("Id", "Body", "Code", "Description", "LastUpdated", "Subject", "Variables")
VALUES (-7, '<div style=''font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;''><h2 style=''color: #2c3e50;''>Family Link Request</h2><p>Hello <strong>{{FullName}}</strong>,</p><p><strong>{{RequesterName}}</strong> has requested to link their account with yours as a <strong>{{Relationship}}</strong>.</p><div style=''text-align: center; margin: 30px 0;''><a href=''{{ProfileUrl}}'' style=''background: #c5a059; color: #fff; padding: 12px 30px; text-decoration: none; border-radius: 8px; font-weight: bold; border: 1px solid #c5a059;''>Review Request</a></div><p>Please log in to your profile to accept or decline this request.</p></div>', 'FAMILY_LINK_REQUEST', 'Family link request email', TIMESTAMPTZ '2026-03-21T15:37:55.635894Z', 'New Family Link Request from {{RequesterName}}', '[''FullName'', ''RequesterName'', ''Relationship'', ''ProfileUrl'']');
INSERT INTO "EmailTemplates" ("Id", "Body", "Code", "Description", "LastUpdated", "Subject", "Variables")
VALUES (-6, '<div style=''font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;''><h2 style=''color: #2c3e50;''>Payment Status Update</h2><p>Dear <strong>{{FullName}}</strong>,</p><p>The status of your transaction <strong>{{TrxID}}</strong> has been updated to <strong>{{Status}}</strong>.</p><p>Thank you for your contribution.</p></div>', 'PAYMENT_STATUS_UPDATED', 'Payment status update email', TIMESTAMPTZ '2026-03-21T15:37:55.635891Z', 'Payment Status Updated: {{Status}}', '[''FullName'', ''TrxID'', ''Status'']');
INSERT INTO "EmailTemplates" ("Id", "Body", "Code", "Description", "LastUpdated", "Subject", "Variables")
VALUES (-5, '<div style=''font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;''><h2 style=''color: #2c3e50;''>Payment Received</h2><p>Dear <strong>{{FullName}}</strong>,</p><p>We have successfully received your payment. It is currently under verification.</p><div style=''background: #f8f9fa; padding: 15px; border-radius: 5px;''><p><strong>Amount:</strong> {{Amount}} BDT</p><p><strong>Transaction ID:</strong> {{TrxID}}</p></div><p>You will be notified once the payment is verified.</p></div>', 'PAYMENT_RECEIVED', 'Payment received acknowledgment', TIMESTAMPTZ '2026-03-21T15:37:55.635888Z', 'Payment Received: {{Amount}} BDT', '[''FullName'', ''Amount'', ''TrxID'']');
INSERT INTO "EmailTemplates" ("Id", "Body", "Code", "Description", "LastUpdated", "Subject", "Variables")
VALUES (-4, '<div style=''font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;''><h2 style=''color: #e74c3c;''>Application Status Update</h2><p>Dear <strong>{{FullName}}</strong>,</p><p>Thank you for your interest in the GHC Alumni Association. After reviewing your application, we regret to inform you that we cannot approve it at this time.</p><div style=''background: #fdf2f2; padding: 15px; border-radius: 5px; border-left: 5px solid #e74c3c;''><p><strong>Reason:</strong> {{Reason}}</p></div><p>If you believe this is an error, please contact the association office.</p></div>', 'APPLICATION_REJECTED', 'Application rejection email', TIMESTAMPTZ '2026-03-21T15:37:55.635883Z', 'Update on your GHCAA Membership Application', '[''FullName'', ''Reason'']');
INSERT INTO "EmailTemplates" ("Id", "Body", "Code", "Description", "LastUpdated", "Subject", "Variables")
VALUES (-3, '<div style=''font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;''><h2 style=''color: #c5a059;''>Password Reset</h2><p>Hello <strong>{{FullName}}</strong>,</p><p>An administrator has initiated a password reset for your GHCAA account. Click below to set a new password — the link is valid for 24 hours.</p><div style=''text-align: center; margin: 30px 0;''><a href=''{{ResetUrl}}'' style=''background: #111; color: #c5a059; padding: 12px 30px; text-decoration: none; border-radius: 8px; font-weight: 800; display: inline-block; border: 1px solid #c5a059;''>Reset My Password</a></div><p style=''color: #666; font-size: 0.9rem;''>If you did not request this, please ignore this email.</p></div>', 'PASSWORD_RESET', 'Password reset email', TIMESTAMPTZ '2026-03-21T15:37:55.63587Z', 'GHCAA Account Password Reset', '[''FullName'', ''ResetUrl'']');
INSERT INTO "EmailTemplates" ("Id", "Body", "Code", "Description", "LastUpdated", "Subject", "Variables")
VALUES (-2, '<div style=''font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;''><h2 style=''color: #2c3e50;''>Welcome to GHCAA</h2><p>Dear <strong>{{FullName}}</strong>,</p><p>Your membership has been approved! We are excited to have you as part of our community.</p><div style=''background: #e8f4fd; padding: 15px; border-radius: 5px; border-left: 4px solid #3498db;''><p><strong>Membership No:</strong> {{MembershipNumber}}</p><p><strong>Default Password:</strong> <code style=''background:#fff; padding:2px 5px;''>{{DefaultPassword}}</code></p></div><p>Please log in and change your password immediately.</p></div>', 'WELCOME_EMAIL', 'Welcome email', TIMESTAMPTZ '2026-03-21T15:37:55.635862Z', 'Welcome to GHC Alumni Association!', '[''FullName'', ''MembershipNumber'', ''DefaultPassword'']');
INSERT INTO "EmailTemplates" ("Id", "Body", "Code", "Description", "LastUpdated", "Subject", "Variables")
VALUES (-1, '<div style=''font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 500px;''><h2 style=''color: #2c3e50;''>Verification Code</h2><p>Hello <strong>{{FullName}}</strong> metallic,</p><p>Your security code is:</p><div style=''font-size: 24px; font-weight: bold; background: #f8f9fa; padding: 15px; text-align: center; border-radius: 5px; color: #c5a059; border: 1px solid #eee;''>{{OtpCode}}</div><p>Valid for 10 minutes. Do not share this code.</p></div>', 'OTP_EMAIL', 'OTP verification email', TIMESTAMPTZ '2026-03-21T15:37:55.634957Z', 'GHCAA Verification Code: {{OtpCode}}', '[''FullName'', ''OtpCode'']');

