ALTER TABLE "MembershipFeeConfigs" ADD "EffectiveTo" timestamp with time zone;

ALTER TABLE "MembershipFeeConfigs" ADD "IsActive" boolean NOT NULL DEFAULT FALSE;

ALTER TABLE "AlumniEvents" ADD "EndDate" timestamp with time zone NOT NULL DEFAULT TIMESTAMPTZ '-infinity';

