CREATE INDEX "IX_SavedPaymentMethods_MemberId" ON "SavedPaymentMethods" ("MemberId");

SELECT setval(
    pg_get_serial_sequence('"MembershipFeeConfigs"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "MembershipFeeConfigs") + 1,
        nextval(pg_get_serial_sequence('"MembershipFeeConfigs"', 'Id'))),
    false);
SELECT setval(
    pg_get_serial_sequence('"SavedPaymentMethods"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "SavedPaymentMethods") + 1,
        nextval(pg_get_serial_sequence('"SavedPaymentMethods"', 'Id'))),
    false);

