VALUES ('20260401195524_AddMemberSignaturePath_PgSql', '9.0.0');

ALTER TABLE "Members" ADD "CertificatePath" text;

ALTER TABLE "Members" ADD "ECChangeReason" text;

ALTER TABLE "Members" ADD "MembershipChangeReason" text;

ALTER TABLE "Members" ADD "PaymentProofPath" text;

ALTER TABLE "AlumniEvents" ADD "HasWaitlist" boolean NOT NULL DEFAULT FALSE;

ALTER TABLE "AlumniEvents" ADD "ParticipantLimit" integer;

CREATE TABLE "Constitutions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Version" text NOT NULL,
    "Content" text NOT NULL,
    "PdfUrl" text,
    "EffectiveDate" timestamp with time zone NOT NULL,
    "SupersededDate" timestamp with time zone,
    "IsActive" boolean NOT NULL,
    "ChangeSummary" text NOT NULL,
    CONSTRAINT "PK_Constitutions" PRIMARY KEY ("Id")
);

CREATE TABLE "MentorshipRequests" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RequesterId" integer NOT NULL,
    "MentorId" integer NOT NULL,
    "Message" character varying(500),
    "Domain" character varying(200),
    "Status" integer NOT NULL,
    "ResponseNote" character varying(500),
    "RequestedAt" timestamp with time zone NOT NULL,
    "RespondedAt" timestamp with time zone,
    CONSTRAINT "PK_MentorshipRequests" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_MentorshipRequests_Members_MentorId" FOREIGN KEY ("MentorId") REFERENCES "Members" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_MentorshipRequests_Members_RequesterId" FOREIGN KEY ("RequesterId") REFERENCES "Members" ("Id") ON DELETE CASCADE
);

CREATE TABLE "NewsCollaborators" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "NewsPostId" integer NOT NULL,
    "UserId" integer NOT NULL,
    "AddedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_NewsCollaborators" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_NewsCollaborators_NewsPosts_NewsPostId" FOREIGN KEY ("NewsPostId") REFERENCES "NewsPosts" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_NewsCollaborators_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AmendmentVotes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ConstitutionId" integer NOT NULL,
    "MemberId" integer NOT NULL,
    "IsFor" boolean NOT NULL,
    "Comments" text,
    "VotedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_AmendmentVotes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AmendmentVotes_Constitutions_ConstitutionId" FOREIGN KEY ("ConstitutionId") REFERENCES "Constitutions" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AmendmentVotes_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id") ON DELETE CASCADE
);

