ALTER TABLE "Users" ADD "FacebookId" text;

ALTER TABLE "Users" ADD "GoogleId" text;

ALTER TABLE "NewsPosts" ADD "ExternalCollaborators" text;

ALTER TABLE "Members" ADD "IsProfileComplete" boolean NOT NULL DEFAULT FALSE;

CREATE TABLE "Polls" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" text NOT NULL,
    "Description" text,
    "AllowMultipleChoice" boolean NOT NULL,
    "IsActive" boolean NOT NULL,
    "IsArchived" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "ExpiryDate" timestamp with time zone,
    "CreatedBy" integer NOT NULL,
    CONSTRAINT "PK_Polls" PRIMARY KEY ("Id")
);

CREATE TABLE "PollOptions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PollId" integer NOT NULL,
    "OptionText" text NOT NULL,
    CONSTRAINT "PK_PollOptions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PollOptions_Polls_PollId" FOREIGN KEY ("PollId") REFERENCES "Polls" ("Id") ON DELETE CASCADE
);

CREATE TABLE "PollVotes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PollId" integer NOT NULL,
    "PollOptionId" integer NOT NULL,
    "MemberId" integer NOT NULL,
    "VotedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PollVotes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PollVotes_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_PollVotes_PollOptions_PollOptionId" FOREIGN KEY ("PollOptionId") REFERENCES "PollOptions" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_PollVotes_Polls_PollId" FOREIGN KEY ("PollId") REFERENCES "Polls" ("Id") ON DELETE CASCADE
);

